class Token:
    NUMBER, PLUS, MINUS, MULTIPLY, DIVIDE, LPAREN, RPAREN, EOF = (
        'NUMBER', 'PLUS', 'MINUS', 'MULTIPLY', 'DIVIDE', 'LPAREN', 'RPAREN', 'EOF'
    )

    def __init__(self, type_, value):
        self.type = type_
        self.value = value


class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return Token(Token.NUMBER, self._number())
            if self.current_char == '+':
                self.advance()
                return Token(Token.PLUS, '+')
            if self.current_char == '-':
                self.advance()
                return Token(Token.MINUS, '-')
            if self.current_char == '*':
                self.advance()
                return Token(Token.MULTIPLY, '*')
            if self.current_char == '/':
                self.advance()
                return Token(Token.DIVIDE, '/')
            if self.current_char == '(':
                self.advance()
                return Token(Token.LPAREN, '(')
            if self.current_char == ')':
                self.advance()
                return Token(Token.RPAREN, ')')
            self.error()
        return Token(Token.EOF, None)

    def _number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)


class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception("Invalid syntax")

    def eat(self, token_type):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.type == Token.NUMBER:
            self.eat(Token.NUMBER)
            return token.value
        elif token.type == Token.LPAREN:
            self.eat(Token.LPAREN)
            result = self.expr()
            self.eat(Token.RPAREN)
            return result

    def term(self):
        result = self.factor()
        while self.current_token.type in (Token.MULTIPLY, Token.DIVIDE):
            token = self.current_token
            if token.type == Token.MULTIPLY:
                self.eat(Token.MULTIPLY)
                result *= self.factor()
            elif token.type == Token.DIVIDE:
                self.eat(Token.DIVIDE)
                denominator = self.factor()
                if denominator == 0:
                    raise ZeroDivisionError("division by zero")
                result /= denominator
        return result

    def expr(self):
        result = self.term()
        while self.current_token.type in (Token.PLUS, Token.MINUS):
            token = self.current_token
            if token.type == Token.PLUS:
                self.eat(Token.PLUS)
                result += self.term()
            elif token.type == Token.MINUS:
                self.eat(Token.MINUS)
                result -= self.term()
        return result


