def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm 
    for converting infix expressions to postfix notation and then evaluates 
    the resulting postfix expression.
    """
    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def to_postfix(expression):
        output = []
        operators = []
        number = ''

        for char in expression:
            if char.isdigit() or char == '.':
                number += char
            else:
                if number:
                    output.append(float(number))
                    number = ''
                if char in "+-*/":
                    while (operators and precedence(operators[-1]) >= precedence(char)):
                        output.append(operators.pop())
                    operators.append(char)
                elif char == '(':
                    operators.append(char)
                elif char == ')':
                    while operators and operators[-1] != '(':
                        output.append(operators.pop())
                    operators.pop()  # Pop the '('

        if number:
            output.append(float(number))

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    stack.append(a / b)
        return stack[0]

    postfix_expr = to_postfix(expr)
    return evaluate_postfix(postfix_expr)

def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using a recursive descent parser 
    which processes the expression based on operator precedence directly.
    """
    class Parser:
        def __init__(self, expression):
            self.tokens = self.tokenize(expression)
            self.pos = 0

        def tokenize(self, expr):
            tokens = []
            num = ''
            for char in expr:
                if char.isdigit() or char == '.':
                    num += char
                else:
                    if num:
                        tokens.append(float(num))
                        num = ''
                    if char in "+-*/()":
                        tokens.append(char)
            if num:
                tokens.append(float(num))
            return tokens

        def parse_expression(self):
            value = self.parse_term()
            while self.pos < len(self.tokens):
                token = self.tokens[self.pos]
                if token in ('+', '-'):
                    self.pos += 1
                    right_value = self.parse_term()
                    value = value + right_value if token == '+' else value - right_value
                else:
                    break
            return value

        def parse_term(self):
            value = self.parse_factor()
            while self.pos < len(self.tokens):
                token = self.tokens[self.pos]
                if token in ('*', '/'):
                    self.pos += 1
                    right_value = self.parse_factor()
                    value = value * right_value if token == '*' else value / right_value
                else:
                    break
            return value

        def parse_factor(self):
            token = self.tokens[self.pos]
            if isinstance(token, float):
                self.pos += 1
                return token
            elif token == '(':
                self.pos += 1
                value = self.parse_expression()
                self.pos += 1  # Skip ')'
                return value
            raise ValueError("Unexpected token")

    parser = Parser(expr)
    return parser.parse_expression()

def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm 
    to convert the expression into Reverse Polish Notation (RPN), 
    which is then evaluated.
    """
    def shunting_yard(expression):
        output_queue = []
        operator_stack = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        tokens = tokenize(expression)

        for token in tokens:
            if isinstance(token, float):
                output_queue.append(token)
            elif token in precedence:
                while (operator_stack and 
                       operator_stack[-1] in precedence and 
                       precedence[operator_stack[-1]] >= precedence[token]):
                    output_queue.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output_queue.append(operator_stack.pop())
                operator_stack.pop()  # pop the '('

        while operator_stack:
            output_queue.append(operator_stack.pop())

        return output_queue

    def evaluate_rpn(rpn):
        stack = []
        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    def tokenize(expression):
        tokens = []
        num = ''
        for char in expression:
            if char.isdigit() or char == '.':
                num += char
            else:
                if num:
                    tokens.append(float(num))
                    num = ''
                if char in "+-*/()":
                    tokens.append(char)
        if num:
            tokens.append(float(num))
        return tokens

    rpn = shunting_yard(expr)
    return evaluate_rpn(rpn)
